const results = $input.all();
const summary = {
  run_id: results[0]?.json?.run_id || '',
  sources_attempted: 3,
  sources_succeeded: results.filter(r => !r.json?.error).length,
  sources_failed: results.filter(r => r.json?.error).length,
  total_brokers_upserted: results.reduce((sum, r) => sum + (r.json?.brokers_upserted || 0), 0),
  total_brokers_skipped: results.reduce((sum, r) => sum + (r.json?.brokers_skipped || 0), 0),
  failed_sources: results.filter(r => r.json?.error).map(r => r.json?.source_name),
  completed_at: new Date().toISOString()
};
return [{ json: summary }];

const crypto = require('crypto');
const items = $input.all();
const payload = {
  source: 'github_big_ass_list',
  discovered_at: new Date().toISOString(),
  brokers: items.map(i => i.json)
};
const body = JSON.stringify(payload);
const secret = $('Workflow Input').item.json.n8n_webhook_secret;
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(body).digest('hex');
return [{ json: { payload, body, signature } }];
